local G=require('genome');local A=require('anatomy');local P=require('body_parts');local D=require('anatomical_development');local S=require('persistence');local B=require('biology');local R=require('rendering');local T={}
local root;local function write(name,value) local f=assert(io.open(root..'/'..name,'wb'));f:write(value);f:close() end
local function seed(i) return (20261112+i*104729)%2147483647 end
local function make(i) local g=G.new(G.rng(seed(i)));return A.generate(g,{seed=seed(i),nutrition=1,oxygen=1,temperature=37}),g end
local function rebind(a) return S.rebind(G.copy(a)) end
local function count(t) local n=0;for _ in pairs(t) do n=n+1 end;return n end
function T.run()
 root=love.filesystem.isFused() and love.filesystem.getSourceBaseDirectory() or love.filesystem.getSource();local lines,failed={},0
 local function test(name,fn) local ok,why=xpcall(fn,debug.traceback);lines[#lines+1]=(ok and 'PASS ' or 'FAIL ')..name;if not ok then failed=failed+1;lines[#lines+1]=type(why)=='table' and S.encode(why) or tostring(why) end end
 local a,g=make(19)
 test('Canonical deterministic genetic anatomy and same environment',function() local b=A.generate(G.copy(g),a.development);assert(G.valid(g) and #g.chromosomes==24);assert(S.encode(a)==S.encode(b));assert(a.generator=='skeletal-reconstruction-v2') end)
 test('Connected vertebral, rib, girdle and appendage skeleton',function() local names={};for _,c in ipairs(a.structures) do names[c.anatomicalName]=true;assert(c.parent==nil or a.components[c.parent]);assert(c.integrity==1 and c.path and #c.path>=2) end;assert(#a.structures>#a.regions and names['protective rib arch'] and names['shoulder / axial girdle']);for i,r in ipairs(a.regions) do assert(i==1 or r.parent<i);assert(r.structure and a.components[r.structure]) end end)
 test('Bone volume, density, dimensions and mass are distinct',function() for _,c in ipairs(a.structures) do assert(c.length>0 and c.width>0 and c.density>0 and c.volume>=0);assert(math.abs(c.mass-c.density*c.volume)<1e-10);assert(c.targetVolume and c.targetDensity) end end)
 test('Joints connect real supports and have finite ordered limits',function() for _,j in ipairs(a.joints) do assert(a.components[j.parent] and a.components[j.child]);assert(j.maximum>j.minimum and j.range>0);assert(a.regions[j.partId].parent) end end)
 test('Antagonistic muscles and tendons attach to movable supports',function() assert(#a.muscles>=#a.regions);for _,c in ipairs(a.muscles) do assert(c.origin~=c.insertion and a.components[c.origin] and a.components[c.insertion]);assert(c.volume>0 and c.density>0 and c.functionalRole and c.mass>0) end end)
 test('Protected organ placement, containment and collision validation',function() assert(P.validate(a));local b=rebind(a);b.organs[1].cx=99999;assert(not P.validate(b));b=rebind(a);b.organs[#b.organs+1]=G.copy(b.organs[1]);assert(not P.validate(b));local names={};for _,o in ipairs(a.organs) do names[o.type]=true end;assert(names.Kidney and names.Gonad and names.Brain) end)
 test('Hierarchical nerves reach muscles, digits, sensory and internal organs',function() local reached={};for _,o in ipairs(a.organs) do if o.type=='Brain' then reached[o.id]=true end end;for i=1,100 do for _,n in ipairs(a.nerves) do if reached[n.from] then reached[n.to]=true end end end;for _,c in ipairs(a.muscles) do assert(reached[c.id]) end;for _,c in ipairs(a.organs) do assert(reached[c.id]) end;for _,s in ipairs(a.sensors) do assert(reached[s.id]) end end)
 test('Distal bases have individual phalanges, joints and supported claws',function() local digits=0;for _,r in ipairs(a.regions) do if r.partType=='digit' then digits=digits+1;assert(r.digitIndex and r.digitSegment and a.components[r.structure]) end;if r.partType=='claw' and r.specialization=='terminal keratin' then assert(a.regions[r.parent].partType=='digit') end end;assert(digits>0) end)
 test('Fat reserve changes actual tissue volume, mass and envelope',function() local b=rebind(a);D.setProgress(b,1,{fatFraction=.1});local lean=A.capabilities(b,g);local _,leanTips=require('tissue_surface').geometry(b);D.setProgress(b,1,{fatFraction=1});local full=A.capabilities(b,g);assert(full.mass>lean.mass and full.physicalMass.Fat>lean.physicalMass.Fat);local _,fullTips=require('tissue_surface').geometry(b);assert(S.encode(fullTips)~=S.encode(leanTips)) end)
 test('Skin covers every developed region with dorsal and ventral protection',function() for _,r in ipairs(a.regions) do local n=0;for _,c in ipairs(a.skin) do if c.regionId==r.id then n=n+1;assert(c.volume>0 and c.thickness>0) end end;assert(n==2) end end)
 test('Dorsal chest defense does not protect ventral abdomen',function() local b=rebind(a);local before=P.defense(b,2,'ventral');for _,c in ipairs(b.skin) do if c.regionId==1 and c.surface=='dorsal' then c.armor=100 end end;assert(P.defense(b,1,'dorsal')>99 and P.defense(b,2,'ventral')==before) end)
 test('Force, speed and supply derive from developed tissues and condition',function() local b=rebind(a);for _,m in ipairs(b.muscles) do m.condition=0 end;local c=A.capabilities(b,g);assert(c.force==0 and c.speed==0 and a.caps.force>0);for _,o in ipairs(b.organs) do if o.type=='Heart' then o.condition=0 end end;assert(A.capabilities(b,g).supply==0);local n=rebind(a);for _,edge in ipairs(n.nerves) do edge.condition=0 end;assert(A.capabilities(n,g).coordination==0) end)
 test('Anatomical inheritance and meaningful direct allele changes',function() local h=G.copy(g);for _,ch in ipairs(h.chromosomes) do for _,l in ipairs(ch.loci) do l.b=l.a end end;local child=assert(G.fertilize(G.gamete(h,G.rng(4),1,0),G.gamete(h,G.rng(5),2,0)));local p=A.generate(h);local c=A.generate(child);assert(p.headCount==c.headCount and p.appendageCount==c.appendageCount and p.caps.mass==c.caps.mass);local edited=G.copy(g);for _,i in ipairs({6,14}) do edited.chromosomes[i].loci[2].a=0;edited.chromosomes[i].loci[2].b=0 end;local x=A.generate(edited);assert(x.appendageCount==0 and x.headCount==0 and #x.regions<#a.regions) end)
 test('Persistent region/component table identity throughout development',function() local b=rebind(a);local r,c=b.regions[4],b.components[10];for i=0,30 do D.setProgress(b,i/30);assert(b.regions[4]==r and b.components[10]==c and r.uid==a.regions[4].uid and c.id==10) end end)
 test('No mature structure pops into existence; bounded dimension/mass changes',function() local b=rebind(a);D.setProgress(b,0);local last={};local mass=0;for i=0,400 do D.setProgress(b,i/400);for id,r in ipairs(b.regions) do if last[id] then assert(math.abs(r.length-last[id])<=a.regions[id].length*.025+1e-8) end;last[id]=r.length;if r.parent and i/400<=r.activation then assert(r.length==0 and r.volume==0) end end;assert(math.abs(b.massLedger.mass-mass)<a.massLedger.mass*.025+1e-7);mass=b.massLedger.mass end end)
 test('Developing tissue mass conservation and nonnegative cavity budgets',function() local b=rebind(a);for step=0,20 do D.setProgress(b,step/20);local totals={};for _,c in ipairs(b.components) do assert(c.volume>=0 and c.mass>=0 and math.abs(c.mass-c.volume*c.density)<1e-9);totals[c.regionId]=(totals[c.regionId] or 0)+c.volume end;for _,r in ipairs(b.regions) do assert((totals[r.id] or 0)<=r.volume+1e-9 and r.freeVolume>=0) end end end)
 test('Growth preserves skeletal, muscle and neural references at all ages',function() local b=rebind(a);for step=0,20 do D.setProgress(b,step/20);for _,r in ipairs(b.regions) do assert(b.components[r.structure].regionId==r.id) end;for _,m in ipairs(b.muscles) do assert(b.components[m.origin] and b.components[m.insertion]) end;for _,n in ipairs(b.nerves) do assert(b.components[n.from] and b.components[n.to]) end end end)
 test('Elapsed growth independent of rendering frame rate and time partition',function() local x,y=rebind(a),rebind(a);D.setProgress(x,0);D.setProgress(y,0);for i=1,600 do D.advance(x,.05) end;for i=1,30 do D.advance(y,1) end;for i,r in ipairs(x.regions) do assert(math.abs(r.length-y.regions[i].length)<1e-8) end;assert(math.abs(x.massLedger.mass-y.massLedger.mass)<1e-8) end)
 test('Nutrition and oxygen constrain actual developmental rate',function() local x,y=rebind(a),rebind(a);D.setProgress(x,0);D.setProgress(y,0);D.advance(x,50,{nutrition=1,oxygen=1,temperature=37});D.advance(y,50,{nutrition=.3,oxygen=.4,temperature=37});assert(x.growth>y.growth and x.massLedger.mass>y.massLedger.mass) end)
 test('Saved growing anatomy resumes without identity or progress reset',function() local state=B.new(7);local b=rebind(a);D.setProgress(b,.90);local o=assert(B.spawn(state,g,'test',0,.5,.5,b));local decoded=assert(S.decode('return '..S.encode(state),B));local loaded=decoded.organisms[1];assert(loaded.anatomy.growthModel.progress==.90 and loaded.anatomy.parts==loaded.anatomy.regions);D.advance(o.anatomy,1);D.advance(loaded.anatomy,1);assert(o.anatomy.massLedger.mass==loaded.anatomy.massLedger.mass) end)
 test('Old legacy, region and anatomy-v1 records remain unchanged',function() local v1=require('anatomical_growth').generate(g);local loaded=S.rebind(G.copy(v1));assert(loaded.anatomicalVersion==1 and not loaded.growthModel);assert(A.capabilities(loaded,g).mass>0);local old=A.procedural(g);assert(not old.anatomicalVersion and A.capabilities(old,g).mass>0);assert(A.generate(g,{generator='legacy'}).generator=='legacy-fallback') end)
 test('Development failure retains its actual anatomy without fallback',function() local b=A.generate(g,{nutrition=0,oxygen=0,temperature=0});assert(not b.viable and b.generator=='skeletal-reconstruction-v2' and not b.technicalFallback) end)
 test('Incubation releases growing same-ID tissue graph; juvenile growth continues',function() local Dev=require('development');local embryo=Dev.new(1,g,'test',0,{nutrition=1,oxygen=1,temperature=37});local region=embryo.anatomy.regions[1];local ok;for i=1,2000 do ok=Dev.update(embryo,.1);if ok~=nil then break end end;assert(ok==true and embryo.anatomy.regions[1]==region and embryo.anatomy.growth<1,table.concat(embryo.anatomy.failures,'; '));local state=B.new(1);local o=assert(B.spawn(state,g,'test',0,.5,.5,embryo.anatomy));o.worldId='terrarium';local before=region.length;B.update(state,.2);assert(region.length>=before and o.anatomy.regions[1]==region and o.age>0 and o.stats) end)
 test('Recorded biological samples equal continuous simulation at same times',function() local records=D.record(a,20);local b=rebind(a);D.setProgress(b,0);for i=0,20 do if i>0 then D.advance(b,b.growthModel.duration/20,{fatFraction=.7}) end;assert(math.abs(b.massLedger.mass-records[i+1].mass)<1e-7) end end)
 test('Joint poses carry skeletal paths and descendants within limits',function() local pose=require('anatomical_rendering').pose(a,1.2);for _,j in ipairs(pose.joints) do assert(j.playbackAngle>=j.minimum and j.playbackAngle<=j.maximum) end;for i,c in ipairs(pose.structures) do assert(c.id==a.structures[i].id) end;for _,c in ipairs(pose.components) do if c.path then assert(c.path[1].x==c.path[1].x) end end end)
 test('Older unfinished embryos migrate to continuous state without progress loss',function() local embryo={id=9,genome=G.copy(g),conditions={nutrition=1,oxygen=1,temperature=37},progress=.2,tissues={}};require('development').update(embryo,0);assert(math.abs(embryo.progress-.2)<1e-8 and embryo.anatomy.growthModel and embryo.anatomy.growth>0) end)
 local audits={}
 for _,n in ipairs({100,1000}) do
  local report={count=n,viable=0,failures=0,errors=0,heads={},appendages={},symmetry={},postures={},supports={},configurations={},failureReasons={},samples={},minMass=math.huge,maxMass=0,totalStructures=0,totalMuscles=0,totalRegions=0,previousStructures=0,previousMuscles=0}
  local function inc(t,k) t[k]=(t[k] or 0)+1 end
  for i=1,n do local ok,b=pcall(make,i);if not ok then report.errors=report.errors+1;report.samples[#report.samples+1]={seed=seed(i),error=tostring(b)} else
   report.viable=report.viable+(b.viable and 1 or 0);report.failures=report.failures+(b.viable and 0 or 1);inc(report.heads,b.headCount);inc(report.appendages,b.appendageCount);inc(report.symmetry,b.symmetry);inc(report.postures,b.posture);inc(report.supports,b.supportStrategy)
   local skeletal={};for _,c in ipairs(b.structures) do inc(skeletal,c.anatomicalName) end
   local signature=b.symmetry..'/'..b.appendageCount..'/'..b.headCount..'/'..#b.structures..'/'..#b.joints..'/'..math.floor(b.bodyOrientation*4);inc(report.configurations,signature)
   for _,why in ipairs(b.failures) do inc(report.failureReasons,why) end;report.totalStructures=report.totalStructures+#b.structures;report.totalMuscles=report.totalMuscles+#b.muscles;report.totalRegions=report.totalRegions+#b.regions;report.minMass=math.min(report.minMass,b.caps.mass);report.maxMass=math.max(report.maxMass,b.caps.mass)
   if i<=100 then local old=require('anatomical_growth').generate(G.new(G.rng(seed(i))));report.previousStructures=report.previousStructures+#old.structures;report.previousMuscles=report.previousMuscles+#old.muscles end
   report.samples[#report.samples+1]={seed=seed(i),viable=b.viable,heads=b.headCount,appendages=b.appendageCount,regions=#b.regions,structures=#b.structures,joints=#b.joints,muscles=#b.muscles,nerves=#b.nerves,mass=b.caps.mass,skeletalOrganization=skeletal,orientation=b.bodyOrientation,failures=b.failures}
  end end
  audits[n]=report;write('reconstruction-audit-'..n..'.lua','return '..S.encode(report))
  write('docs/RECONSTRUCTION_AUDIT_'..n..'.md',table.concat({'# Actual '..n..'-genome reconstruction audit','','Unfiltered canonical genomes. Seed = (20261112 + i * 104729) mod 2147483647, i=1..'..n..'. Nutrition/oxygen 1; 98.6 F. No retries or viability filtering.','',string.format('Viable %d; biological failures %d; technical errors %d; skeletal/axis configurations %d.',report.viable,report.failures,report.errors,count(report.configurations)),'','Appendages: '..S.encode(report.appendages),'Heads: '..S.encode(report.heads),'Symmetry: '..S.encode(report.symmetry),'Support strategies: '..S.encode(report.supports),'Postures: '..S.encode(report.postures),'',string.format('Mass %.5f–%.5f oz. Mean regions %.2f; supports %.2f; muscle bundles %.2f.',report.minMass,report.maxMass,report.totalRegions/n,report.totalStructures/n,report.totalMuscles/n),'First 100 prior-generator means: supports '..(report.previousStructures/100)..'; muscles '..(report.previousMuscles/100)..'. Same seeds. New supports include actual vertebral/rib/girdle/cranial/phalangeal organization, listed per sample in the data export.','','Failure reasons: '..S.encode(report.failureReasons),'','Contact sheet selection: first 20 genomes of this same audit, including failures.'},'\n'))
 end
 test('1000 actual genomes show non-quadruped, skeletal and orientation diversity',function() local r=audits[1000];assert(r.errors==0 and r.viable>0 and r.appendages[0] and r.appendages[2] and r.appendages[6] and r.heads[0] and r.heads[2]);assert(r.appendages[4]<600) end)
 test('Same real renderer produces side contact sheet, layers and growth sequence',function()
  local canvas=love.graphics.newCanvas(1600,1300);love.graphics.push('all');love.graphics.setCanvas(canvas);love.graphics.clear(.045,.075,.09);love.graphics.setFont(love.graphics.newFont(13));love.graphics.setColor(.84,.94,.9);love.graphics.print('CELLARIUM / RECONSTRUCTION / FIRST 20 UNFILTERED GENOMES / failures retained',20,16)
  for i=1,20 do local b,h=make(i);local x,y=((i-1)%4)*400,math.floor((i-1)/4)*250+50;love.graphics.setColor(.075,.12,.14);love.graphics.rectangle('fill',x+8,y,384,236,6);local scale=R.fitScale(b,345,165,2);local cx,cy=(b.bounds.minx+b.bounds.maxx)/2,(b.bounds.miny+b.bounds.maxy)/2;R.draw({anatomy=b,genome=h,caps=b.caps,alive=true,maturity=1,behavior='Resting'},x+200-cx*scale,y+90-cy*scale,scale,0,'External');love.graphics.setColor(b.viable and .6 or 1,.8,.72);love.graphics.print('Seed '..seed(i)..' / '..(b.viable and 'VIABLE' or 'FAILED'),x+18,y+181);love.graphics.setColor(.65,.77,.8);love.graphics.print(b.appendageCount..' limbs / '..b.headCount..' heads / '..#b.structures..' supports',x+18,y+203) end
  love.graphics.setCanvas();write('docs/RECONSTRUCTION_CONTACT_SHEET.png',canvas:newImageData():encode('png'):getString());love.graphics.pop()
  canvas=love.graphics.newCanvas(1600,950);love.graphics.push('all');love.graphics.setCanvas(canvas);love.graphics.clear(.045,.075,.09);local b=rebind(a);local times={0,.08,.18,.3,.43,.56,.64,.75,.86,1};local records={}
  for i,t in ipairs(times) do D.setProgress(b,t,{fatFraction=.7});records[#records+1]={progress=t,mass=b.massLedger.mass,regions=G.copy(b.regions),components=G.copy(b.components)};local x,y=((i-1)%5)*320,math.floor((i-1)/5)*450+30;local scale=R.fitScale(a,290,155,1.6);local cx,cy=(a.bounds.minx+a.bounds.maxx)/2,(a.bounds.miny+a.bounds.maxy)/2;local o={anatomy=b,alive=true,maturity=1,behavior='Resting'};R.draw(o,x+160-cx*scale,y+110-cy*scale,scale,0,'External');R.draw(o,x+160-cx*scale,y+300-cy*scale,scale,0,{Skeleton=true,Muscle=true,Organs=true,Nervous=true});love.graphics.setColor(.78,.9,.85);love.graphics.print(string.format('%.0f%% / %.4f oz',t*100,b.massLedger.mass),x+20,y+390) end
  love.graphics.setCanvas();write('docs/RECONSTRUCTION_GROWTH_SEQUENCE.png',canvas:newImageData():encode('png'):getString());write('docs/RECONSTRUCTION_GROWTH_RECORDS.lua','return '..S.encode(records));love.graphics.pop()
  for _,layer in ipairs(R.layers) do R.draw({anatomy=a,alive=true,maturity=1,behavior='Resting'},0,0,1,0,layer) end;R.drawTopDown({anatomy=a,alive=true,maturity=1,behavior='Resting',angle=0},0,0,1,0)
 end)
 test('Developer playback uses actual current anatomy and elapsed time without skipped delta',function() local U=require('anatomy_dev_ui');U.generate(seed(1));U.frame=1;U.playhead=0;U.playing=true;U.update(1);local p=U.playhead;local current=U.frameAnatomy();assert(current~=U.anatomy and current.growth==p and current.caps.mass<U.anatomy.caps.mass);U.update(3);assert(math.abs(U.playhead-4/18)<1e-10);U.playing=false;U.frame=61;assert(math.abs(U.frameAnatomy().growth-.5)<1e-10) end)
 test('Settings generator, seed, archive, timeline and inspection callbacks render',function() local app=require('desktop_app');local U=require('anatomy_dev_ui');local state=B.new(4);require('desktop_model').ensure(state);require('desktop_host').monitors={};local hits={};local function draw() hits={};app.draw(state,{register=function(x,y,w,h,fn,label) hits[label]=fn end}) end;app.page='Settings';draw();hits['Anatomy Generator / developer tool']();U.frame=121;draw();assert(hits['Save Genome'] and hits.Restart and hits.Step and hits['Seek biological timeline'] and hits['Structure >']);hits['Save Genome']();assert(#state.materials==1);hits.Restart();assert(U.frame==1);draw();hits.Step();assert(U.frame==2);local canvas=love.graphics.newCanvas(1440,900);love.graphics.push('all');love.graphics.setCanvas(canvas);U.frame=86;draw();love.graphics.setCanvas();write('docs/RECONSTRUCTION_GENERATOR.png',canvas:newImageData():encode('png'):getString());love.graphics.pop() end)
 lines[#lines+1]=string.format('%d groups executed; %d failures.',#lines,failed);write('reconstruction-test-results.txt',table.concat(lines,'\n'));assert(failed==0,table.concat(lines,'\n'));return table.concat(lines,'\n')
end
